{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "What is the outside diameter and weight of 1728F cable?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "28.4mm OD and 482 kg per km, built as 144 ribbons of twelve fibers in an all-dielectric (GYFDXPH) construction."
      }
    },
    {
      "@type": "Question",
      "name": "Which fiber type does 1728F cable use?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "G.652D single-mode as standard, or G.657A1 bend-insensitive single-mode, on Fujikura preform glass."
      }
    },
    {
      "@type": "Question",
      "name": "What is the lead time for 1728F cable?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "6 to 8 weeks from PO, up to 10 weeks for custom builds, with 2 to 3 week expedited air freight available. Domestic ribbon at high count is frequently quoted in months."
      }
    },
    {
      "@type": "Question",
      "name": "Why use ribbon instead of loose tube at 1728F?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Ribbon keeps fibers in twelve-fiber rows, so a splicer joins twelve at a time on a mass fusion machine instead of one by one. At 1728 fibers that is a large saving in splice time on every joint."
      }
    },
    {
      "@type": "Question",
      "name": "Can I go higher than 1728F?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yes. 6912F rollable ribbon is available at 38.0mm OD and 1064 kg per km (LSZH), built as 432 ribbons of sixteen fibers on G.657A1 or G.657A2. Ribbon cable runs from 12F to 6912F, so the count can be matched to the route."
      }
    },
    {
      "@type": "Question",
      "name": "What about the outdoor jacket, duct size, bend radius, pulling tension and reel?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "These depend on the jacket and the route, so they are confirmed with your quote. Send the route length, duct size and install method and we will return the full spec with price and lead time."
      }
    }
  ]
